      "newContent": "package com.acme.shortener.cache;

import java.time.Instant;

/** What the cache knows about a code: it redirects somewhere, or it is known not to exist. */
public sealed interface CacheEntry {

  /**
   * @param expiresAt when the link stops redirecting; {@code null}: never. Callers check it on
   *     every hit, so no cache level can serve a link past its expiry.
   */
  record Found(String originalUrl, Instant expiresAt) implements CacheEntry {

    /** A link that never expires. */
    public Found(String originalUrl) {
      this(originalUrl, null);
    }
  }

  /** Negative entry: unknown or deleted code. Short TTL; stops scan-DoS reaching the DB. */
  record NotFound() implements CacheEntry {}

  NotFound NOT_FOUND = new NotFound();
}
