      "newContent": "package com.acme.shortener.cache;

import java.time.Duration;
import java.time.Instant;
import java.util.Optional;

/** Read-through cache for redirects (ADR-0003). Empty means a miss at every level. */
public interface LinkCache {

  Optional<CacheEntry> get(String code);

  /** Caches an active link that never expires. Overwrites any negative entry for the same code. */
  void putFound(String code, String originalUrl);

  /**
   * Caches an active link that expires at {@code expiresAt}, {@code timeLeft} from now: no level
   * keeps it longer than that. The default caches nothing, which is always safe.
   */
  default void putExpiring(String code, String originalUrl, Instant expiresAt, Duration timeLeft) {}

  void putNotFound(String code);

  /** Removes the code from every level (on delete, and wherever a cached answer is stale). */
  void evict(String code);
}
