import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import org.springframework.data.redis.core.StringRedisTemplate;

/**
 * L2 in Redis. One key per code: {@code link:{code}} holding {@code E:<epoch millis>:<url>} for a
 * link (0 when it never expires) or {@code N} for a negative entry, so a later create simply
 * overwrites a negative entry. Values in the older {@code U:<url>} format are still read.
 */
public final class RedisLinkCache implements RemoteLinkCache {

  static final String KEY_PREFIX = "link:";
  private static final String FOUND = "U:";
  private static final String EXPIRING = "E:";
  private static final String NOT_FOUND = "N";

  private final StringRedisTemplate redis;

  public RedisLinkCache(StringRedisTemplate redis) {
    this.redis = redis;
  }

  @Override
  public Optional<CacheEntry> get(String code) {
    String value = redis.opsForValue().get(KEY_PREFIX + code);
    if (value == null) {
      return Optional.empty();
    }
    if (value.startsWith(FOUND)) {
      return Optional.of(new CacheEntry.Found(value.substring(FOUND.length())));
    }
    if (value.startsWith(EXPIRING)) {
      int colon = value.indexOf(':', EXPIRING.length());
      if (colon < 0) {
        return Optional.empty(); // unreadable: a miss, so the database answers
      }
      long millis = Long.parseLong(value.substring(EXPIRING.length(), colon));
      Instant expiresAt = millis == 0 ? null : Instant.ofEpochMilli(millis);
      return Optional.of(new CacheEntry.Found(value.substring(colon + 1), expiresAt));
    }
    return Optional.of(CacheEntry.NOT_FOUND);
  }

  @Override
  public void put(String code, CacheEntry entry, Duration ttl) {
    String value =
        switch (entry) {
          case CacheEntry.Found found ->
              EXPIRING
                  + (found.expiresAt() == null ? 0 : found.expiresAt().toEpochMilli())
                  + ":"
                  + found.originalUrl();
          case CacheEntry.NotFound notFound -> NOT_FOUND;
        };
    redis.opsForValue().set(KEY_PREFIX + code, value, ttl);
  }

  @Override
  public void delete(String code) {
    redis.delete(KEY_PREFIX + code);
  }
}
